/**
 * Analytics event catalogue. Every event has a UUID `id` used for de-duplication (unique index in
 * PostgreSQL). Gameplay-critical events are generated by the server only; clients may report the
 * events listed in CLIENT_EVENTS. See docs/ANALYTICS.md for definitions.
 */
import { z } from 'zod';
import { CHARACTER_IDS } from '../game-rules/characters.js';
import { MAP_IDS } from '../maps/types.js';

export const ANALYTICS_EVENTS = [
  'app_opened',
  'session_started',
  'session_ended',
  'profile_created',
  'tutorial_completed',
  'lobby_created',
  'lobby_joined',
  'lobby_left',
  'match_started',
  'match_completed',
  'match_abandoned',
  'character_selected',
  'map_played',
  'invite_created',
  'invite_opened',
  'connection_error',
  'reconnect_attempted',
  'reconnect_succeeded',
  'client_error',
  'shop_purchase',
  'mod_bought',
  'case_opened',
  'payment_completed',
  'email_linked',
] as const;
export type AnalyticsEventName = (typeof ANALYTICS_EVENTS)[number];

/** Events a client is allowed to submit through POST /api/events. */
export const CLIENT_EVENTS = [
  'app_opened',
  'session_ended',
  'tutorial_completed',
  'character_selected',
  'invite_opened',
  'connection_error',
  'reconnect_attempted',
  'reconnect_succeeded',
  'client_error',
] as const satisfies readonly AnalyticsEventName[];
export type ClientEventName = (typeof CLIENT_EVENTS)[number];

const short = z.string().max(120);
const platform = z.enum(['telegram_ios', 'telegram_android', 'telegram_desktop', 'telegram_web', 'telegram_other', 'browser_mobile', 'browser_desktop', 'unknown']);
export type Platform = z.infer<typeof platform>;
/** Client-reported platform (not cryptographically verified; used for analytics breakdowns only). */
export const PlatformSchema = platform;

export const CLIENT_EVENT_PROPS = {
  app_opened: z.object({ platform, startParam: z.string().max(64).optional(), referrer: short.optional() }).strict(),
  session_ended: z.object({ durationMs: z.number().int().min(0).max(86_400_000) }).strict(),
  tutorial_completed: z.object({ step: z.string().max(32).optional() }).strict(),
  character_selected: z.object({ character: z.enum(CHARACTER_IDS) }).strict(),
  invite_opened: z.object({ code: z.string().max(32), result: z.enum(['joinable', 'full', 'in_progress', 'finished', 'expired', 'not_found']) }).strict(),
  connection_error: z.object({ stage: z.enum(['connect', 'auth', 'join', 'gameplay']), code: z.string().max(40).optional() }).strict(),
  reconnect_attempted: z.object({ attempt: z.number().int().min(1).max(100) }).strict(),
  reconnect_succeeded: z.object({ attempt: z.number().int().min(1).max(100), downtimeMs: z.number().int().min(0).max(600_000) }).strict(),
  client_error: z
    .object({
      component: z.string().max(40),
      category: z.string().max(40),
      message: z.string().max(300),
      clientVersion: z.string().max(32).optional(),
    })
    .strict(),
} satisfies Record<ClientEventName, z.ZodTypeAny>;

export const SERVER_EVENT_PROPS = {
  session_started: z.object({ platform, method: z.enum(['telegram', 'dev', 'guest', 'email']) }),
  profile_created: z.object({ method: z.enum(['telegram', 'dev', 'guest']) }),
  lobby_created: z.object({ roomId: z.string(), mapId: z.enum(MAP_IDS), isPrivate: z.boolean() }),
  lobby_joined: z.object({ roomId: z.string(), viaInvite: z.boolean() }),
  lobby_left: z.object({ roomId: z.string(), phase: z.string() }),
  match_started: z.object({ matchId: z.string(), roomId: z.string(), mapId: z.enum(MAP_IDS), players: z.number().int() }),
  match_completed: z.object({ matchId: z.string(), mapId: z.enum(MAP_IDS), durationMs: z.number().int(), players: z.number().int(), reason: z.string() }),
  match_abandoned: z.object({ matchId: z.string(), mapId: z.enum(MAP_IDS), phase: z.string() }),
  map_played: z.object({ matchId: z.string(), mapId: z.enum(MAP_IDS) }),
  invite_created: z.object({ code: z.string(), roomId: z.string() }),
  shop_purchase: z.object({ kind: z.enum(['weapon', 'character', 'gadget']), item: z.string(), currency: z.enum(['tokens', 'diamonds']), amount: z.number().int() }),
  mod_bought: z.object({ weapon: z.string(), mod: z.string(), cost: z.number().int() }),
  case_opened: z.object({ weapon: z.string(), rarity: z.enum(['rare', 'epic', 'legendary']), price: z.number().int() }),
  payment_completed: z.object({ provider: z.string(), packId: z.string(), diamonds: z.number().int(), amountCents: z.number().int() }),
  email_linked: z.object({}),
} as const;

export const ClientEventEnvelopeSchema = z
  .object({
    id: z.string().uuid(),
    name: z.enum(CLIENT_EVENTS),
    ts: z.number().int().positive(),
    props: z.record(z.unknown()).default({}),
  })
  .strict();
export type ClientEventEnvelope = z.infer<typeof ClientEventEnvelopeSchema>;

export const EventsBatchSchema = z.object({ events: z.array(ClientEventEnvelopeSchema).min(1).max(50) }).strict();

/** Validates props of a client event; returns parsed props or null. */
export function parseClientEventProps(name: ClientEventName, props: unknown): Record<string, unknown> | null {
  const r = CLIENT_EVENT_PROPS[name].safeParse(props);
  return r.success ? (r.data as Record<string, unknown>) : null;
}
